methods.docstring:
A validated event-name string for listening markup;
stimulus_event(:change) resolves across the declared
controllers, stimulus_event(:controller, :change) pins one.

examples.text:
attrs = Poetry::Core::HTML::Attributes.new(class: "btn", disabled: true)
attrs.merge_classes!("btn-primary")
attrs.to_attributes # => { "class" => "btn btn-primary", "disabled" => "disabled" }

attrs = Poetry::Core::HTML::Attributes.new(data: { controller: "dropdown" })
attrs.merge_if_not_set!(class: "btn", data: { controller: "modal", action: "click->dropdown#toggle" })
# Result: class: "btn", data: { controller: "dropdown", action: "click->dropdown#toggle" }

attrs = Poetry::Core::HTML::Attributes.new(data: { controller: "dropdown" })
new_attrs = attrs.merge_stimulus({ action: "click->modal#open", target: "output" })
new_attrs["data"] # => { "controller" => "dropdown", "action" => "click->modal#open", "target" => "output" }

attrs = Poetry::Core::HTML::Attributes.new
attrs.merge_stimulus!({ controller: "dropdown", action: "click->dropdown#toggle" })
attrs["data"] # => { "controller" => "dropdown", "action" => "click->dropdown#toggle" }

attrs = Poetry::Core::HTML::Attributes.new(
  class: "btn btn-primary",
  disabled: true,
  id: nil,
  data: { id: 1, controller: "dropdown", target: nil },
  aria: { label: "Close", hidden: nil }
)
attrs.to_attributes
# => {
#   "class" => "btn btn-primary",
#   "disabled" => "disabled",
#   "data-id" => "1",
#   "data-controller" => "dropdown",
#   "aria-label" => "Close"
# }

builder = Poetry::Core::Stimulus::Builder.new("menu", html_attributes,
  values: { visible: true },
  actions: { show: :mouseenter, hide: :mouseleave },
  classes: { active: "bg-blue-500" }
)

Builder.new("modal", html_attributes,
  values: { open: false, size: "large" },
  actions: { toggle: :click, close: { on: :keydown, at: :window } }
)

objects.docstring:
Evaluates one use_stimulus block; #elements is the harvest. The
block's vocabulary is {#on} (declare an element) and {#event}
(build a validated event name).

examples.text:
merger = Poetry::Core::Stimulus::Merger.new
attrs1 = { data: { controller: "dropdown modal" } }
attrs2 = { data: { controller: "dropdown tooltip" } }
merged = merger.merge_attributes(attrs1, attrs2)
# => { data: { controller: "dropdown modal tooltip" } }

merger = Poetry::Core::Stimulus::Merger.new
attrs1 = { data: { controller: "form", action: "submit->form#save" } }
attrs2 = { data: { action: "keyup->form#validate" } }
merged = merger.merge_attributes(attrs1, attrs2)
# => { data: { controller: "form", action: "submit->form#save keyup->form#validate" } }

merge(
  { controller: "dropdown", action: "click->dropdown#toggle" },
  { controller: "dropdown tooltip", target_value: "main" }
)
# => { controller: "dropdown tooltip", action: "click->dropdown#toggle", target_value: "main" }
